<?php
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM services WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$search=trim((string)($_GET['q']??''));$filter=$_GET['status']??'active';$sql='SELECT * FROM services WHERE 1=1';$params=[];if($filter!=='all'){$sql.=' AND status=?';$params[]=$filter==='archived'?'archived':'active';}if($search!==''){$sql.=' AND (name LIKE ? OR service_code LIKE ?)';$params[]="%$search%";$params[]="%$search%";}$sql.=' ORDER BY name';$q=db()->prepare($sql);$q->execute($params);$services=$q->fetchAll();
?>
<div class="page-heading"><div><div class="eyebrow">Service catalog</div><h1>Services</h1><p>Manage treatment names, session duration, and pricing in Philippine Peso.</p></div><?php if(is_admin()):?><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#serviceModal"><i class="bi bi-plus-lg me-1"></i>Add service</button><?php endif;?></div>
<div class="card"><div class="card-body border-bottom d-flex flex-wrap gap-2 justify-content-between"><form method="get" class="search-box"><input type="hidden" name="page" value="services"><i class="bi bi-search"></i><input class="form-control" name="q" value="<?=h($search)?>" placeholder="Search services"></form><div class="d-flex gap-2"><?php foreach(['active'=>'Active','archived'=>'Archived','all'=>'All'] as $k=>$v):?><a href="<?=h(app_page_url('services',['status'=>$k]))?>" class="btn btn-sm <?=$filter===$k?'btn-primary':'btn-outline-secondary'?>"><?=$v?></a><?php endforeach;?></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Service</th><th>Duration</th><th>Price</th><th>Status</th><th>Last updated</th><?php if(is_admin()):?><th></th><?php endif;?></tr></thead><tbody><?php if(!$services)echo table_empty(is_admin()?6:5);foreach($services as $s):?><tr><td><strong><?=h($s['name'])?></strong><div class="small-muted"><?=h($s['service_code'])?> · <?=h($s['description']?:'No description')?></div></td><td><?=h($s['duration_minutes'])?> min</td><td class="fw-bold"><?=money($s['price'])?></td><td><?=status_badge($s['status'])?></td><td><?=date_label($s['updated_at'])?></td><?php if(is_admin()):?><td class="text-end"><a class="btn btn-sm btn-light" href="<?=h(app_page_url('services',['edit'=>$s['id']]))?>"><i class="bi bi-pencil"></i></a> <?=post_form_start('toggle_service',app_page_url('services',['status'=>$filter]))?><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn btn-sm btn-light" data-confirm="Change this service status?"><i class="bi bi-<?=($s['status']==='active'?'archive':'arrow-counterclockwise')?>"></i></button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><div class="card-body small-muted">Prices are stored and displayed in PHP (₱). Transaction items retain the price at checkout.</div></div>
<?php if(is_admin()):?><div class="modal fade" id="serviceModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><?=post_form_start('save_service',app_page_url('services'))?><div class="modal-header"><h5 class="modal-title"><?=$edit?'Edit service':'Add service'?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="mb-3"><label class="form-label">Service name *</label><input class="form-control" name="name" required value="<?=h($edit['name']??'')?>"></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="2"><?=h($edit['description']??'')?></textarea></div><div class="row g-3"><div class="col-6"><label class="form-label">Duration (minutes) *</label><input class="form-control" type="number" min="1" max="600" name="duration_minutes" required value="<?=h($edit['duration_minutes']??60)?>"></div><div class="col-6"><label class="form-label">Price (₱) *</label><input class="form-control" type="number" min="0" step="0.01" name="price" required value="<?=h($edit['price']??'')?>"></div></div><?php if($edit):?><div class="mt-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" <?=selected($edit['status'],'active')?>>Active</option><option value="archived" <?=selected($edit['status'],'archived')?>>Archived</option></select></div><?php endif;?></div><div class="modal-footer"><a href="<?=h(app_page_url('services'))?>" class="btn btn-light">Cancel</a><button class="btn btn-primary">Save service</button></form></div></div></div></div><?php if($edit):?><script>document.addEventListener('DOMContentLoaded',()=>new bootstrap.Modal(document.getElementById('serviceModal')).show());</script><?php endif;?><?php endif;?>
